<span class="line"><span style="color:#B392F0;">grep</span><span style="color:#79B8FF;"> -i</span><span style="color:#9ECBFF;"> &quot;&lt;script\\|javascript:\\|onload\\|onerror&quot;</span><span style="color:#9ECBFF;"> /var/log/nginx/access.log</span></span>
